  "كربون": ["co2", "hypercapnia", "cabin"],
  "نوم": ["sleep", "circadian", "fatigue"],
  "ارق": ["sleep", "circadian", "fatigue"],
  "ارهاق": ["fatigue", "sleep", "ear", "facial_ear", "ear_fatigue", "perclos", "blink"],
  "تعب": ["fatigue", "sleep", "ear", "facial_ear", "ear_fatigue", "perclos", "blink"],
  "سكر": ["glucose", "glycemic", "metabolic"],
  "جلوكوز": ["glucose", "glycemic", "metabolic"],
  "توازن": ["balance", "posture", "vestibular", "ataxia"],
  "مشي": ["posture", "symmetry", "locomotion", "balance"],
  "حركه": ["symmetry", "posture", "locomotion"],
  "دوخه": ["vestibular", "dizziness", "orthostatic", "balance"],
  "دوار": ["vestibular", "dizziness", "orthostatic"],
  "قلب": ["heart", "cardio", "arrhythmia", "orthostatic"],
  "نبض": ["heart", "cardio", "rate"],
  "عين": ["sans", "ocular", "vision", "eye"],
  "عيون": ["sans", "ocular", "vision"],
  "رؤيه": ["sans", "ocular", "vision"],
  "حراره": ["temp", "temperature", "fever"],
